#!/usr/bin/env python3
# Generate the IDNA derived property and joining type tables used by
# utils/idna.c from the IANA idna-tables-properties.csv and the Unicode
# DerivedJoiningType.txt files.

import argparse
import sys

HEADER = """/* This file is generated by idna-derived-props-gen.py
 * DO NOT EDIT BY HAND
 */
#ifndef _NETSURFY_UTILS_IDNA_PROPS_H_
#define _NETSURFY_UTILS_IDNA_PROPS_H_

typedef enum idna_property {
	IDNA_P_PVALID		= 1,
	IDNA_P_CONTEXTJ		= 2,
	IDNA_P_CONTEXTO		= 3,
	IDNA_P_DISALLOWED	= 4,
	IDNA_P_UNASSIGNED	= 5
} idna_property;

typedef enum idna_unicode_jt {
	IDNA_UNICODE_JT_U	= 0,
	IDNA_UNICODE_JT_C	= 1,
	IDNA_UNICODE_JT_D	= 2,
	IDNA_UNICODE_JT_R	= 3,
	IDNA_UNICODE_JT_T	= 4,
	IDNA_UNICODE_JT_L	= 5
} idna_unicode_jt;

typedef struct idna_table {
	int32_t start;
	int32_t end;
	union p {
		idna_property property;
		idna_unicode_jt jt;
	} p;
} idna_table;

idna_table idna_derived[] = {
"""


def properties(path):
    with open(path, encoding="utf-8") as f:
        next(f, None)
        for line in f:
            items = line.rstrip("\n").split(",")
            if len(items) < 2:
                continue
            points = items[0].split("-")
            yield points[0], points[-1], items[1]


def joining_types(path):
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.rstrip("\n")
            if line == "" or line.startswith("#"):
                continue
            items = line.split(";")
            points = items[0].strip().split("..")
            yield points[0], points[-1], items[1].strip()[0]


def generate(props, joining):
    out = [HEADER]
    for start, end, prop in props:
        out.append("\t{ 0x%s, 0x%s, .p.property = IDNA_P_%s },\n" % (start, end, prop))
    out.append("\t{ 0, 0, .p.property = 0}\n};\n\nidna_table idna_joiningtype[] = {\n")
    for start, end, jt in joining:
        out.append("\t{ 0x%s, 0x%s, .p.jt = IDNA_UNICODE_JT_%s },\n" % (start, end, jt))
    out.append("\t{ 0, 0, .p.jt = 0}\n};\n#endif\n")
    return "".join(out)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("-o", "--output")
    parser.add_argument("-p", "--properties", default="idna-tables-properties.csv")
    parser.add_argument("-j", "--joining", default="DerivedJoiningType.txt")
    args = parser.parse_args()
    text = generate(properties(args.properties), joining_types(args.joining))
    if args.output:
        with open(args.output, "x", encoding="utf-8") as f:
            f.write(text)
    else:
        sys.stdout.write(text)


if __name__ == "__main__":
    main()
